model:
def int capacity = 0;
def int free = 0;
def int reserved = 0;
def int allocated = 0;
def int request = 0;
def int moved = 0;
def int observed = 0;

state Pool {
    state Intake;
    state Transaction {
        state Hold {
            enter {
                moved = request;
                if [free < moved] { moved = free; }
                free = free - moved;
                reserved = reserved + moved;
            }
        }
        state Apply {
            enter {
                moved = request;
                reserved = reserved - moved;
                allocated = allocated + moved;
            }
            during {
                observed = free + reserved;
                observed = observed + allocated;
            }
        }
        state Return {
            exit {
                moved = request;
                if [allocated < moved] { moved = allocated; }
                allocated = allocated - moved;
                free = free + moved;
            }
        }
        [*] -> Hold;
        Hold -> Apply : if [reserved >= request];
        Apply -> Return : if [allocated >= request];
        Return -> [*];
    }
    state Verify {
        during {
            observed = free + reserved;
            observed = observed + allocated;
        }
    }

    [*] -> Intake;
    Intake -> Transaction : if [free >= request];
    Transaction -> Verify;
    Verify -> Intake;
}

query:
init state("Pool.Intake") havoc *;
assume at 0: request > 0;
assume at 0: capacity > request;
assume at 0: free >= 0 && reserved >= 0 && allocated >= 0;
assume at 0: capacity == free + reserved + allocated;
assume at 4: free < 0 || reserved < 0 || allocated < 0 || capacity != free + reserved + allocated;
check reach <= 4: true;

model:
param int maximum = 0;
param int quantum = 0;
def int display = 0;
def int saved = 0;
def int snapshot = 0;
def int proposal = 0;
def int margin = 0;
def int delta = 0;
def int refund = 0;
def int audit = 0;
state DoseEditor {
    event Open;
    event Increase;
    event Confirm;
    event Undo;
    state Idle;
    state Editing {
        enter {
            snapshot = display;
            proposal = display;
            margin = maximum - proposal;
        }
        exit { audit = saved - snapshot; }
        state Adjust {
            state Choose;
            state Review;
            state Trim {
                enter {
                    refund = quantum - margin;
                    proposal = proposal - refund;
                    margin = margin + refund;
                }
            }
            [*] -> Choose;
            Choose -> Review : /Increase + [quantum > 0] effect {
                if [margin > quantum * 2] {
                    delta = quantum * 2;
                } else {
                    delta = quantum;
                }
                proposal = proposal + delta;
                margin = margin - delta;
            };
            Review -> Choose : /Undo effect {
                proposal = snapshot;
                margin = maximum - proposal;
            };
            Review -> Trim : if [margin < quantum];
            Review -> [*] : if [margin >= quantum];
            Trim -> [*] : if [margin >= quantum];
        }
        state Ready;
        [*] -> Adjust;
        Adjust -> Ready;
        Ready -> [*] : /Confirm + [margin >= quantum] effect {
            saved = proposal;
        };
    }
    state Committed {
        enter { display = saved; }
        during { audit = display - snapshot; }
    }
    [*] -> Idle;
    Idle -> Editing : /Open + [display >= 0 && display < maximum];
    Editing -> Committed;
    Committed -> Idle;
}

query:
init cold havoc *;
assume at 0: quantum > 0;
assume at 0: maximum > quantum * 4;
assume at 0: display >= 0 && display < maximum;
assume at 0: saved < maximum;
assume at 0: proposal + margin == maximum;
assume at 6: saved >= maximum;
check reach <= 6: true;

